/**
 *  新增sys_time_hour以及sys_time_day
 */


SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


DROP TABLE IF EXISTS `sys_time_day`;
CREATE TABLE `sys_time_day`  (
  `id` int(4) NOT NULL AUTO_INCREMENT,
  `time` datetime(0) NOT NULL COMMENT 'time',
  `ts` bigint(20) NOT NULL COMMENT 'milliseconds',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_time`(`time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 103637 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;



DROP TABLE IF EXISTS `sys_time_hour`;
CREATE TABLE `sys_time_hour`  (
  `id` int(4) NOT NULL AUTO_INCREMENT,
  `time` datetime(0) NOT NULL COMMENT 'time',
  `ts` bigint(20) NOT NULL COMMENT 'milliseconds',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_time`(`time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 159183 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_time_hour
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;

